17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (owner.getRegistrationDate() == null) {
111	            owner.setRegistrationDate(LocalDate.now());
112	        }
113	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
114	        this.clinicService.saveOwner(owner);
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        headers.setLocation(UriComponentsBuilder.newInstance()
117	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
118	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
119	    }
120	
121	    /**
122	     * Determines whether an owner already exists that uses the same telephone number
123	     * as the given one. Telephone numbers must be unique across all owners. The
124	     * comparison ignores letter case and any surrounding or repeated whitespace.
125	     */
126	    private boolean isDuplicateOwner(Owner owner) {
127	        String telephone = normalize(owner.getTelephone());
128	        return this.clinicService.findAllOwners().stream()
129	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
130	    }
131	
132	    /**
133	     * Determines whether another owner already uses the same email address as the given one.
134	     * Email addresses, when supplied, must be unique across all owners. An owner without an
135	     * email address is never considered a duplicate. The comparison ignores letter case and
136	     * any surrounding or repeated whitespace.
137	     */
138	    private boolean isDuplicateEmail(Owner owner) {
139	        String email = normalize(owner.getEmail());
140	        if (email == null || email.isEmpty()) {
141	            return false;
142	        }
143	        return this.clinicService.findAllOwners().stream()
144	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
145	    }
146	
147	    /**
148	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
149	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
150	     * and "John Smith" normalize to the same key and so count as the same person.
151	     */
152	    private static String normalize(String value) {
153	        if (value == null) {
154	            return null;
155	        }
156	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
171	        this.clinicService.saveOwner(currentOwner);
172	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Transactional
177	    @Override
178	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        this.clinicService.deleteOwner(owner);
184	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
190	        Owner owner = this.clinicService.findOwnerById(ownerId);
191	        if (owner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        HttpHeaders headers = new HttpHeaders();
195	        Pet pet = petMapper.toPet(petFieldsDto);
196	        owner.setId(ownerId);
197	        pet.setOwner(owner);
198	        pet.getType().setName(null);
199	        this.clinicService.savePet(pet);
200	        PetDto petDto = petMapper.toPetDto(pet);
201	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
202	            .buildAndExpand(pet.getId()).toUri());
203	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
209	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
210	        if (currentOwner != null) {
211	            Pet currentPet = this.clinicService.findPetById(petId);
212	            if (currentPet != null) {
213	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
214	                currentPet.setName(petFieldsDto.getName());
215	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
216	                this.clinicService.savePet(currentPet);
217	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
218	            }
219	        }
220	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
226	        HttpHeaders headers = new HttpHeaders();
227	        Visit visit = visitMapper.toVisit(visitFieldsDto);
228	        Pet pet = new Pet();
229	        pet.setId(petId);
230	        visit.setPet(pet);
231	        this.clinicService.saveVisit(visit);
232	        VisitDto visitDto = visitMapper.toVisitDto(visit);
233	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
234	            .buildAndExpand(visit.getId()).toUri());
235	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
236	    }
237	
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
242	        Owner owner = this.clinicService.findOwnerById(ownerId);
243	        if (owner != null) {
244	            Pet pet = owner.getPet(petId);
245	            if (pet != null) {
246	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
247	            }
248	        }
249	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
250	    }
251	}
